import {templates,makeObject} from './project.js';
import {thumbnail} from './graphics.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const templateDescriptions={blank:'Your world, from scratch.',platformer:'Jump, collect coins, and reach the flag.',rhythm:'An evenly spaced course to build on.',topdown:'Explore freely in four directions.',space:'Move freely and shoot with Space.',puzzle:'Find your way through a coin maze.',runner:'Keep moving. Time your jumps.'};
export function mountSetup({root,project,onComplete,onCancel,notify}){
 let step=0,busy=0;const excluded=new Set();project.assets??=[];
 const categories=[['sprites','player','Sprites & characters','Your player, characters, and animated game art.'],['hazards','hazard','Hazards & enemies','Spikes, enemies, obstacles, or anything dangerous.'],['collectibles','coin','Collectibles & items','Coins, power-ups, keys, and other pickups.'],['environment','platform','Platforms & environment','Surfaces, walls, and the pieces of your world.']];
 const $=s=>root.querySelector(s);
 function render(){root.innerHTML=`<div class="setup-shell"><header class="setup-header"><div class="brand"><span class="mark">◈</span> Playform Studio</div><button id="skip-all">Skip setup →</button></header><main class="setup-stage"><div class="setup-progress"><span class="${step===0?'active':''}">1 · Game assets</span><span class="${step===1?'active':''}">2 · Your game idea</span><span>3 · Studio</span></div><div class="eyebrow">${esc(project.name)} / PROJECT SETUP</div>${step===0?`<h1>What’s going into your game?</h1><div class="setup-assets">${categories.map(([id,type,title,description])=>`<section class="setup-asset ${excluded.has(id)?'disabled':''}"><h3><img src="${thumbnail(type)}" alt="">${title}</h3><input type="file" data-upload="${id}" accept="image/png,image/jpeg,image/webp,image/gif" multiple aria-label="Import ${title}" ${excluded.has(id)?'disabled':''}><div class="setup-upload-list">${project.assets.filter(a=>a.category===id).map(a=>`<img src="${a.data}" alt="${esc(a.name)}" title="${esc(a.name)}">`).join('')}</div><label><input type="checkbox" data-exclude="${id}" ${excluded.has(id)?'checked':''}>My game doesn’t use these</label></section>`).join('')}</div><div class="setup-footer"><button id="cancel-setup">← Back to projects</button><div><button id="skip-assets">Skip assets</button><button class="primary" id="next-step">Continue →</button></div></div>`:`<h1>A little about your game.</h1><label for="game-brief">Your game idea <span class="muted">(optional)</span></label><textarea id="game-brief" maxlength="3000" placeholder="A tiny robot explores a moon base, avoids laser traps, and collects batteries to find a way home…">${esc(project.description||'')}</textarea><label>Choose a starting preset</label><div class="template-picker">${Object.entries(templates).map(([id,name])=>`<button data-template="${id}" class="template-choice ${id===project.template?'selected':''}"><b>${name}</b></button>`).join('')}</div><div class="setup-summary"><span>${project.assets.length} imported assets</span><span>${templates[project.template]}</span><span>Everything is editable</span></div><div class="setup-footer"><button id="back-step">← Assets</button><div><button id="skip-brief">Skip description</button><button class="primary" id="enter-studio">Open studio →</button></div></div>`}</main></div>`;
  $('#skip-all').onclick=()=>finish(true);if(step===0){$('#cancel-setup').onclick=onCancel;$('#next-step').onclick=()=>{if(busy){notify('Please wait for image imports to finish.');return}step=1;render();scrollTo(0,0)};$('#skip-assets').onclick=()=>{if(busy)return;project.assets=[];excluded.clear();step=1;render();scrollTo(0,0)};root.querySelectorAll('[data-exclude]').forEach(c=>c.onchange=()=>{if(c.checked)excluded.add(c.dataset.exclude);else excluded.delete(c.dataset.exclude);render()});root.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{busy++;try{for(const file of input.files){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Choose a PNG, JPEG, WebP or GIF image.');if(file.size>600000)throw Error('Keep each image under 600 KB for device-local project storage.');if(project.assets.reduce((n,a)=>n+a.data.length,0)+file.size*1.4>2000000)throw Error('Imports are limited to 2 MB per project. You can start with smaller images.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});project.assets.push({id:crypto.randomUUID(),name:file.name,category:input.dataset.upload,data})}}catch(e){notify(e.message||'Image import failed.')}finally{busy--;render()}})}else{$('#game-brief').oninput=e=>project.description=e.target.value;$('#back-step').onclick=()=>{step=0;render();scrollTo(0,0)};$('#enter-studio').onclick=()=>finish();$('#skip-brief').onclick=()=>{project.description='';finish()};root.querySelectorAll('[data-template]').forEach(b=>b.onclick=async()=>{const{createProject}=await import('./project.js');const next=createProject(project.name,b.dataset.template);project.objects=next.objects;project.gravity=next.gravity;project.template=next.template;render()})}
 }
 function finish(skip=false){if(busy){notify('Please wait for imports to finish.');return}if(!skip){for(const id of excluded){project.assets=project.assets.filter(a=>a.category!==id);const types={sprites:['player'],hazards:['hazard','enemy'],collectibles:['coin'],environment:['platform']}[id];project.objects=project.objects.filter(o=>!types.includes(o.type))}project.assetCategories=categories.filter(([id])=>!excluded.has(id)).map(([id])=>id)}else{project.assets=[];project.description=''}
  for(const [category,type]of [['sprites','player'],['hazards','hazard'],['collectibles','coin'],['environment','platform']]){const asset=project.assets.find(a=>a.category===category);if(asset)for(const o of project.objects.filter(o=>o.type===type))o.asset=asset.data}onComplete(project)
 }
 render();
}
